const text = $json.csv ?? $json.body ?? $json.response ?? $json.data ?? JSON.stringify($json);
const lines = text.split(/\r?\n/).filter(l => l.trim());
if (lines.length < 2) return [];
const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/, ''));
const rows = lines.slice(1).map(l => {
  const vals = l.split(',');
  const o = {};
  headers.forEach((h, i) => { o[h] = (vals[i] || '').trim().replace(/^"|"$/, ''); });
  return o;
});
return rows.filter(r => {
  const s = String(r.Status || '').trim().toUpperCase();
  return s === '' || s === 'PLANNED';
}).map(r => ({
  json: {
    Season: r.Season, Episode: r.Episode, Title: r.Title, Logline: r.Logline || '',
    MusicUrl: r.MusicUrl || '', RowId: r.RowId || '',
    TargetDuration: Number(r.TargetDuration || 600),
  }
}));

const bible = JSON.parse($json.CHARACTER_BIBLE || '{}');
const epSeason = String($json.Season);
const epEpisode = String($json.Episode);
const text = $json.csv ?? $json.body ?? $json.response ?? $json.data ?? JSON.stringify($json);
const lines = text.split(/\r?\n/).filter(l => l.trim());
if (lines.length < 2) return [];
const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/, ''));
const rows = lines.slice(1).map(l => {
  const vals = l.split(',');
  const o = {};
  headers.forEach((h, i) => { o[h] = (vals[i] || '').trim().replace(/^"|"$/, ''); });
  return o;
});
const scenes = rows.filter(r => {
  const s = String(r.Status || '').trim().toUpperCase();
  return String(r.Season || '').trim() === epSeason
    && String(r.Episode || '').trim() === epEpisode
    && (s === '' || s === 'PENDING');
});
scenes.sort((a, b) => Number(a.SceneNo || 0) - Number(b.SceneNo || 0));
return scenes.map((r, i) => {
  const char = bible[r.Character] || {};
  return {
    json: {
      Season: $json.Season, Episode: $json.Episode, Title: $json.Title,
      EpisodeRowId: $json.RowId, SceneNo: r.SceneNo, Character: r.Character,
      DialogueLine: r.DialogueLine, Action: r.Action, ImagePrompt: r.ImagePrompt || '',
      DurationSeconds: Number(r.DurationSeconds || 6),
      VoiceId: char.voiceId || '', RefImageUrl: char.refImageUrl || '',
      Role: char.role || '', ColorScheme: char.colorScheme || '',
      RowId: r.RowId || (i + 2),
      isLast: i === scenes.length - 1,
    }
  };
});

const style = $json.STYLE_PROMPT || 'Doraemon-style 2D anime, bright flat colors, thick clean black outlines, simple shapes, kawaii';
const prompt = ($json.Action ? $json.Action + '. ' : '') + $json.DialogueLine + ' Featuring ' + $json.Character + ' (' + $json.Role + '), consistent character design, reference image: ' + $json.RefImageUrl + '. ' + style + '. Palette: ' + $json.ColorScheme + '. 16:9, high quality.';
return { json: { imagePrompt: prompt } };

