const rows = lines.slice(1).map(l => {
  const vals = l.split(',');
  const o = {};
  headers.forEach((h, i) => { o[h] = (vals[i] || '').trim().replace(/^"|"$/, ''); });
  return o;
});
const scenes = rows
  .filter(r => String(r.Season || '').trim() === String($json.Season) && String(r.Episode || '').trim() === String($json.Episode) && String(r.SyncedUrl || '').trim() !== '')
  .sort((a, b) => Number(a.SceneNo || 0) - Number(b.SceneNo || 0))
  .map(r => ({
    scene_no: Number(r.SceneNo),
    video_url: r.SyncedUrl,
    audio_url: r.AudioUrl || '',
    dialogue_line: r.DialogueLine || '',
    duration_seconds: Number(r.DurationSeconds || 6)
  }));
const payload = {
  episode_key: 'S' + $json.Season + 'E' + $json.Episode,
  season: $json.Season,
  episode: $json.Episode,
  title: $json.Title,
  music_url: $json.MusicUrl || '',
  target_duration: Number($json.TargetDuration || 600),
  scenes,
  created_at: new Date().toISOString()
};
return { json: { ...$json, assembleBody: JSON.stringify(payload), skipAssembly: scenes.length === 0 } };

